    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = null;

        String line = br.readLine();
        if (line == null) return;
        st = new StringTokenizer(line);
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        long t = Long.parseLong(st.nextToken());

        int[] p = new int[n + 1];
        st = new StringTokenizer(br.readLine());
        for (int i = 1; i <= n; i++) {
            p[i] = Integer.parseInt(st.nextToken());
        }

        int[] g = new int[n + 1];
        int[] prefA = new int[n + 1];
        st = new StringTokenizer(br.readLine());
        for (int i = 1; i <= n; i++) {
            g[i] = Integer.parseInt(st.nextToken());
            prefA[i] = prefA[i - 1] + g[i];
        }

        int maxTotalV = 9 * k;
        int[][] dp = new int[k + 1][maxTotalV + 1];
        int INF = 1_000_000_000;

        for (int j = 0; j <= k; j++) {
            Arrays.fill(dp[j], INF);
        }
        dp[0][0] = 0;

        for (int i = 1; i <= n; i++) {
            int pi = p[i];
            int limitJ = Math.min(i, k);

            for (int j = limitJ; j >= 1; j--) {
                int maxV = 9 * j;
                for (int v = maxV; v >= pi; v--) {
                    if (dp[j - 1][v - pi] < dp[j][v]) {
                        dp[j][v] = dp[j - 1][v - pi];
                    }
                }
            }

            int target = prefA[i];
            for (int j = 0; j <= limitJ; j++) {
                int diff = Math.abs(j - target);
                int maxV = 9 * j;
                for (int v = 0; v <= maxV; v++) {
                    if (dp[j][v] < INF) {
                        dp[j][v] += diff;
                    }
                }
            }
        }

        int ans = 0;
        for (int v = maxTotalV; v >= 0; v--) {
            if (dp[k][v] <= t) {
                ans = v;
                break;
            }
        }

        System.out.println(ans);
    }
}
